mapper.select:
SELECT EXERCISE_ID /* 운동아이디 */ , NAME /* 운동명 */ , BODY_PART_CD , EQUIPMENT_CD , (SELECT DTL_CD_NM FROM CMM_CODE_DTL WHERE COM_CD_ID = 'BODY_PART_CD' AND DTL_CD_ID = E.BODY_PART_CD) AS BODY_PART_NM /* 대표부위코드 */ , (SELECT DTL_CD_NM FROM CMM_CODE_DTL WHERE COM_CD_ID = 'EXERCISE_EQUIPMENT_CD' AND DTL_CD_ID = E.EQUIPMENT_CD) AS EQUIPMENT_NM /* 요구장비코드 */ , IMAGE_FILE_ID /* 이미지파일아이디 */ , REG_DT /* 등록일시 */ , MOD_DT /* 변경일시 */ FROM EXERCISES E
AND E.BODY_PART_CD = #{bodyPartCd}
AND E.EQUIPMENT_CD = #{equipmentCd}
AND E.NAME LIKE '%' || #{name} || '%'
ORDER BY EXERCISE_ID DESC

mapper.insert:
INSERT INTO EXERCISES (
    NAME           /* 운동명 */
  , BODY_PART_CD    /* 대표부위코드 */
  , EQUIPMENT_CD    /* 요구장비코드 */
  , IMAGE_FILE_ID   /* 이미지파일아이디 */
  , REG_DT          /* 등록일시 */
  , MOD_DT          /* 변경일시 */
) VALUES (
    #{dto.name}
  , #{dto.bodyPartCd}
  , #{dto.equipmentCd, jdbcType=VARCHAR}
  , #{dto.imageFileId, jdbcType=NUMERIC}
  , SYSDATE
  , SYSDATE
)

mapper.update:
UPDATE EXERCISES
SET NAME = #{dto.name}
  , BODY_PART_CD = #{dto.bodyPartCd}
  , EQUIPMENT_CD = #{dto.equipmentCd, jdbcType=VARCHAR}
  , IMAGE_FILE_ID = #{dto.imageFileId, jdbcType=NUMERIC}
  , MOD_DT = SYSDATE
WHERE EXERCISE_ID = #{exerciseId, jdbcType=NUMERIC}
